async(page)=>{
 const checks=[],errors=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-entry/';const assert=(ok,m)=>{if(!ok)throw Error(m)};page.on('pageerror',e=>errors.push(e.message));const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')||'null')?.orders.map(o=>[o.id,o.status,o.version]));
 await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:4173/prototype/entry.html');await page.locator('[type=submit]').click();assert((await page.locator('.entry-error').innerText()).includes('DEMO'),'missing credential validation');await page.locator('[name=code]').fill('DEMO');await page.locator('[data-reveal]').click();assert(await page.locator('[name=code]').getAttribute('type')==='text','reveal failed');await page.locator('[data-reveal]').click();await page.locator('summary').click();await page.locator('[name=scenario]').selectOption('network');await page.locator('[type=submit]').click();assert(await page.locator('[type=submit]').isDisabled(),'submit not locked');await page.waitForFunction(()=>document.querySelector('.entry-error').textContent.includes('网络连接失败'));assert(await page.locator('[name=code]').inputValue()==='DEMO','failure lost input');await page.locator('[name=scenario]').selectOption('timeout');await page.locator('[type=submit]').click();await page.waitForFunction(()=>document.querySelector('.entry-error').textContent.includes('等待超时'));await page.locator('[name=scenario]').selectOption('normal');await page.locator('[name=account]').selectOption('A02');await page.locator('[type=submit]').click();await page.locator('.account-preview').waitFor();assert((await page.locator('.account-preview').innerText()).includes('受限调度'),'account scope not applied');assert(await page.locator('[data-nav=access]').count()===0,'restricted login has admin navigation');checks.push('Web 必填、口令显隐、忙碌防重、失败/超时重试、受限账号进入权限范围');
 await page.goto('http://127.0.0.1:4173/prototype/entry.html?kind=driver');await page.setViewportSize({width:390,height:844});await page.screenshot({path:base+'driver-login.png',fullPage:true});await page.locator('summary').click();await page.locator('[data-preview=loading]').click();assert(await page.locator('[aria-busy=true]').count()>0,'loading status missing');await page.screenshot({path:base+'loading-mobile.png'});await page.locator('[data-finish]').click();await page.locator('summary').click();await page.locator('[data-preview=startup]').click();await page.screenshot({path:base+'startup-mobile.png'});await page.locator('[data-finish]').click();await page.locator('[name=code]').fill('DEMO');await page.locator('[type=submit]').click();await page.locator('.startup-screen').waitFor();await page.locator('[data-finish]').click();await page.locator('.message-dialog').waitFor();assert((await page.locator('#message-title').innerText()).includes('安全停车'),'driver notice missing');const before=await state();await page.screenshot({path:base+'driver-home-notice.png'});await page.locator('[data-dismiss]').click();assert(JSON.stringify(before)===JSON.stringify(await state()),'home notice changed order');assert(await page.locator('.driver-app').count()===1,'driver destination wrong');assert(await page.locator('.account-preview').count()===0,'web identity leaked');checks.push('司机 APP 登录→可跳过启动→首页公告；关闭公告不改订单；清除上一后台预览身份');
 await page.locator('.driver-header [data-notices]').click();assert(await page.locator('.notice-center').isVisible(),'mobile notice trigger unbound');await page.locator('[data-notice-close]').click();await page.goto('http://127.0.0.1:4173/prototype/?entry-test=urgent#dispatch');await page.locator('[data-action=busy-scenario]').click();await page.locator('[data-notices]').first().click();await page.locator('[data-strong]').first().click();const strongBefore=await state();assert(await page.locator('[role=alertdialog]').count()===1,'strong dialog role');await page.screenshot({path:base+'strong-notice.png'});await page.locator('[data-dismiss]').click();assert(JSON.stringify(strongBefore)===JSON.stringify(await state()),'strong acknowledgement changed state');assert(await page.locator('.notice.urgent').count()>0,'ack cleared urgent issue');await page.locator('[data-strong]').first().click();await page.locator('[data-open-issue]').click();await page.locator('.message-dialog').waitFor({state:'detached'});assert(await page.locator('.state-axes').count()>0,'issue action did not open order');checks.push('真实演示异常强弹窗：已看到不结案，查看并处理进入对应订单；司机手机消息入口可用');
 await page.emulateMedia({reducedMotion:'reduce'});await page.goto('http://127.0.0.1:4173/prototype/entry.html?kind=customer');await page.locator('summary').click();await page.locator('[data-preview=loading]').click();assert(await page.locator('.load-orbit').evaluate(el=>getComputedStyle(el).animationName)==='none','reduced motion ignored');await page.locator('[data-finish]').click();await page.locator('[name=code]').fill('DEMO');await page.locator('[type=submit]').click();await page.locator('.message-dialog').waitFor();await page.keyboard.press('Escape');await page.locator('.message-dialog').waitFor({state:'detached'});assert(await page.locator('.customer-app').count()===1,'customer destination wrong');await page.emulateMedia({reducedMotion:'no-preference'});checks.push('用户 APP 登录与首页公告、Esc 关闭、减少动态效果设置通过');
 for(const width of [360,390,1440]){await page.setViewportSize({width,height:900});for(const kind of ['web','driver','customer']){await page.goto('http://127.0.0.1:4173/prototype/entry.html?kind='+kind);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'overflow '+kind+width);assert(await page.locator('img').evaluateAll(xs=>xs.every(x=>x.complete&&x.naturalWidth>0)),'logo missing');}}assert(!errors.length,errors.join('\n'));checks.push('三种登录页在 360 / 390 / 1440 宽度无横向溢出，Logo 正常，无脚本错误');return {status:'PASS',checks,pageErrors:errors};
}
